SELECT * FROM (SELECT HOUR(paid_at) AS paid_hour, CASE WHEN amount >= 1690 THEN 'high' WHEN amount >= 540 THEN 'mid' ELSE 'low' END AS amount_bucket, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(method))) AS method_values, SUM(CASE WHEN status = 'REFUNDED' THEN 1 ELSE 0 END) AS refunded_count FROM payments WHERE method IS NOT NULL GROUP BY HOUR(paid_at), CASE WHEN amount >= 1690 THEN 'high' WHEN amount >= 540 THEN 'mid' ELSE 'low' END) AS x WHERE refunded_count > 58 ORDER BY amount_bucket DESC, paid_hour LIMIT 1;
